 {idle:'spr_krisb_idle',intro:'spr_krisb_intro',hurt:'spr_krisb_hurt',defend:'spr_krisb_defend',pose:'spr_kris_y_pose',spin:'spr_krisb_pirouette',blow:'spr_kris_blow_wind',praise:'spr_krisb_bow',attack:'spr_krisb_attack',cast:'spr_krisb_act',item:'spr_krisb_item',act:'spr_krisb_act',defeat:'spr_krisb_defeat',trial:'spr_kris_lawyer'},
 {idle:'spr_susieb_idle',intro:'spr_susie_flowery_greeting_jacket',hurt:'spr_susieb_hurt',defend:'spr_susieb_defend',pose:'spr_susie_m_pose',spin:'spr_susie_pirouette',blow:'spr_susie_blow_wind',praise:'spr_susie_clap',attack:'spr_susieb_attack',cast:'spr_susieb_spell',item:'spr_susieb_item',act:'spr_susieb_act',defeat:'spr_susieb_defeat',trial:'spr_susie_lawyer',throw:'spr_susie_grab'},
